use vstd::prelude::*;

verus! {

fn concatenate(a: Vec<f32>, b: Vec<f32>) -> (res: Vec<f32>)
    ensures
        // (1) Length of result is sum of lengths of a and b
        res.len() == a.len() + b.len(),
        // (2) The first a.len() elements of res agree with a
        forall(|i: usize| i < a.len() ==> res[i] == a[i]),
        // (3) The next b.len() elements of res agree with b
        forall(|j: usize| j < b.len() ==> res[a.len() + j] == b[j]),
{
    // Build the result by pushing elements of a, then b
    let mut res: Vec<f32> = Vec::new();

    // First loop: push all elements of a
    let a_len = a.len();
    let mut i: usize = 0;
    while i < a_len
        invariant
            // res.len() always equals the number of items we've pushed so far
            res.len() == i,
            // All pushed items agree with a
            forall(|k: usize| k < i ==> res[k] == a[k]),
        decreases a_len - i
    {
        res.push(a[i]);
        i += 1;
    }

    // Second loop: push all elements of b
    let b_len = b.len();
    let mut j: usize = 0;
    while j < b_len
        invariant
            // After pushing j items of b, total length is a_len + j
            res.len() == a_len + j,
            // The first a_len items still agree with a
            forall(|k: usize| k < a_len ==> res[k] == a[k]),
            // The next j items agree with the first j items of b
            forall(|k: usize| k < j ==> res[a_len + k] == b[k]),
        decreases b_len - j
    {
        res.push(b[j]);
        j += 1;
    }

    res
}

}

